// ---------- Evaluation report (numbers generated by nids/train.py) ----------
(function renderReport() {
  const $ = (id) => document.getElementById(id);
  const pending = '<span class="pending">pending</span>';
  const pct = (v, d = 2) => (v == null ? pending : (v * 100).toFixed(d) + "%");
  const results = window.NIDS_RESULTS || [];
  const best = (k, lower) => {
    const vals = results.map((r) => r[k]).filter((v) => v != null);
    return vals.length ? (lower ? Math.min(...vals) : Math.max(...vals)) : null;
  };
  const cell = (r, k, fmt, lower) => {
    const v = r[k];
    const b = v != null && v === best(k, lower);
    return `<td class="num${b ? " best" : ""}">${fmt(v)}</td>`;
  };
  results.forEach((r) => {
    const tr = document.createElement("tr");
    tr.innerHTML = `<td>${r.model}</td>` +
      cell(r, "accuracy", (v) => pct(v)) + cell(r, "precision", (v) => pct(v)) + cell(r, "recall", (v) => pct(v)) +
      cell(r, "f1", (v) => pct(v)) + cell(r, "fpr", (v) => pct(v, 3), true) +
      cell(r, "detectionRate", (v) => pct(v)) +
      cell(r, "inferenceMs", (v) => (v == null ? pending : (v * 1000).toFixed(1) + " µs"), true) +
      cell(r, "trainSeconds", (v) => (v == null ? pending : v + " s"), true);
    $("metrics").appendChild(tr);
  });

  const R = window.NIDS_REPORT;
  if (!R) return;
  const total = Object.values(R.rawCounts).reduce((a, b) => a + b, 0);
  $("d-raw").textContent = total.toLocaleString("en-US");
  $("d-train").textContent = R.trainRows.toLocaleString("en-US");
  $("d-test").textContent = R.testRows.toLocaleString("en-US");
  $("d-feat").textContent = R.features;
  $("gen-date").textContent = `· measured ${R.generated}`;

  R.perClass.forEach((c) => {
    const tr = document.createElement("tr");
    const weak = c.f1 < 0.8 ? ' class="weak"' : "";
    tr.innerHTML = `<td${weak}>${c.label}</td><td class="num">${pct(c.precision)}</td><td class="num">${pct(c.recall)}</td>` +
      `<td class="num">${pct(c.f1)}</td><td class="num">${c.support.toLocaleString("en-US")}</td>`;
    $("perclass").appendChild(tr);
  });
  const weak = R.perClass.filter((c) => c.f1 < 0.8).map((c) => c.label);
  $("perclass-note").textContent = weak.length
    ? `Weakest classes: ${weak.join(", ")}. These web attacks share the same target server and port and produce very similar flow shapes, and the dataset has few examples of them, which is a known limitation of CIC-IDS2017. Separating them reliably needs payload (HTTP) features that a flow-level NIDS does not use.`
    : "All classes reach an F1 of at least 80%.";

  const short = (s) => s.replace("DoS ", "").replace("Brute Force", "BF").replace("Web ", "W-").replace("SQL Injection", "SQLi");
  let html = "<tr><th></th>" + R.classes.map((c) => `<th title="${c}">${short(c)}</th>`).join("") + "</tr>";
  R.confusion.forEach((row, i) => {
    const sum = row.reduce((a, b) => a + b, 0) || 1;
    html += `<tr><th title="${R.classes[i]}">${short(R.classes[i])}</th>` + row.map((v, j) => {
      const s = v / sum;
      const color = i === j ? `rgba(61,220,151,${0.12 + s * 0.88})` : `rgba(255,93,108,${s > 0 ? 0.15 + s * 0.85 : 0})`;
      return `<td style="background:${color}" title="${R.classes[i]} → ${R.classes[j]}: ${v} flows (${(s * 100).toFixed(1)}% of row)">${v ? v.toLocaleString("en-US") : ""}</td>`;
    }).join("") + "</tr>";
  });
  $("cm").innerHTML = html;

  const top = R.importance.slice(0, 10);
  const max = top[0].gain;
  $("importance").innerHTML = top.map((f) =>
    `<div class="bar"><span>${f.feature}</span><div><i style="width:${(f.gain / max) * 100}%"></i></div><b>${(f.gain * 100).toFixed(1)}%</b></div>`
  ).join("");
})();

// ---------- Dataset class distribution (log scale) ----------
(function renderDistribution() {
  const R = window.NIDS_REPORT, el = document.getElementById("dist");
  if (!R || !el) return;
  const rows = Object.entries(R.rawCounts).sort((a, b) => b[1] - a[1]);
  const max = Math.log10(rows[0][1]);
  el.innerHTML = rows.map(([k, v]) =>
    `<div class="bar"><span>${k}</span><div><i class="${k === "Benign" ? "benign" : ""}" style="width:${(Math.log10(v) / max) * 100}%"></i></div><b>${v.toLocaleString("en-US")}</b></div>`
  ).join("") + '<p class="note">Bar length uses a log scale.</p>';
})();
